/// <summary>
///     The <c>KCS_DirProductGroupAddressRanking</c> class is the extension of table <c>common</c>
/// </summary>
public class KCS_DirProductGroupAddressRanking extends common
{
}

Method.Source:
/// <summary>
///    AVA <c>find</c> method.
/// </summary>
/// <param name="_productGroupId">
///    <c>KCS_DirProductGroupID</c> as type
/// </param>
/// <param name="_relatedId">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_productGroupAddressRanking">
///    <c>KCS_DirProductGrpAddressRanking</c> as type
/// </param>
/// <param name="_forUpdate">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>KCS_DirProductGroupAddressRanking</c> as return value
/// </returns>
public static KCS_DirProductGroupAddressRanking findKCS_KBVBuildingProjectID(   KCS_DirProductGroupID               _productGroupId,
                                                                                KCS_KBVBuildingProjectID            _relatedId,
                                                                                KCS_DirProductGrpAddressRanking     _productGroupAddressRanking,
                                                                                boolean                             _forUpdate = false)
{
    KCS_DirProductGroupAddressRanking record;

    if(     _productGroupId
        &&  _relatedId      )
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        where   record.ProductGroupId           == _productGroupId
            &&  record.KCS_KBVBuildingProjectID == _relatedId
            &&  record.ProductGrpAddressRanking == _productGroupAddressRanking;
    }

    return record;
}

/// <summary>
///    AVA <c>findCommon</c> method.
/// </summary>
/// <param name="_productGroupId">
///    <c>KCS_DirProductGroupID</c> as type
/// </param>
/// <param name="_common">
///    <c>Common</c> as type
/// </param>
/// <param name="_productGroupAddressRanking">
///    <c>KCS_DirProductGrpAddressRanking</c> as type
/// </param>
/// <param name="_forUpdate">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>KCS_DirProductGroupAddressRanking</c> as return value
/// </returns>
public static KCS_DirProductGroupAddressRanking findCommon( KCS_DirProductGroupID               _productGroupId,
                                                            Common                              _common,
                                                            KCS_DirProductGrpAddressRanking     _productGroupAddressRanking,
                                                            boolean                             _forUpdate = false)
{
    KCS_DirProductGroupAddressRanking record;

    if(     _productGroupId
        &&  _common.RecId   )
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        where   record.ProductGroupId           == _productGroupId
            &&  record.RefTableId               == _common.TableId
            &&  record.RefRecId                 == _common.RecId
            &&  record.ProductGrpAddressRanking == _productGroupAddressRanking;
    }

    return record;
}

/// <summary>
///    AVA <c>exist</c> method.
/// </summary>
/// <param name="_productGroupId">
///    <c>KCS_DirProductGroupID</c> as type
/// </param>
/// <param name="_common">
///    <c>Common</c> as type
/// </param>
/// <param name="_productGroupAddressRanking">
///    <c>KCS_DirProductGrpAddressRanking</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public static boolean exist(KCS_DirProductGroupID           _productGroupId,
                            Common                          _common,
                            KCS_DirProductGrpAddressRanking _productGroupAddressRanking = KCS_DirProductGrpAddressRanking::one)
{
    boolean retVal;

    retVal  =   _productGroupId
            &&  _common.RecId
            &&  (   select firstonly KCS_DirProductGroupAddressRanking
                    where   KCS_DirProductGroupAddressRanking.ProductGroupId            == _productGroupId
                        &&  KCS_DirProductGroupAddressRanking.RefTableId                == _common.TableId
                        &&  KCS_DirProductGroupAddressRanking.RefRecId                  == _common.RecId
                        &&  KCS_DirProductGroupAddressRanking.ProductGrpAddressRanking  == _productGroupAddressRanking).Recid != 0;

    return retVal;
}

/// <summary>
///    AVA <c>createOrUpdateProductGroupAddressRanking</c> method.
/// </summary>
/// <param name="_mapProdGroupAddressRanking">
///    <c>KCS_DirProductGroupID</c> as type
/// </param>
/// <param name="_common">
///    <c>Common</c> as type
/// </param>
public static void createOrUpdateProductGroupAddressRanking(Map     _mapProdGroupAddressRanking,
                                                            Common  _common                     )
{
    MapEnumerator                       mapEnum;
    KCS_DirProductGroupId               productGroupId;
    Container                           conValues;
    int                                 cntContainer;
    DirPartyRecId                       compPartyId;
    KCS_DirProductGrpAddressRanking     ranking;
    KCS_DirProductGroupAddressRanking   newRanking;
    KCS_DirProductGroupAddressRanking   findRanking;

    KCS_KBVBuildingProjectTable         locKCS_KBVBuildingProjectTable;
    smmBusRelTable                      locsmmBusRelTable;
    CustTable                           locCustTable;
    DirPartyTable                       locDirPArtyTable;
    KCS_DirProdGroupAddressType         locKCS_DirProdGroupAddressType;

    if (    _mapProdGroupAddressRanking             == null
        ||  _mapProdGroupAddressRanking.elements()  == 0
        ||  _common.RecId                                   )
    {
        return;
    }

    locKCS_DirProdGroupAddressType  = KCS_DirProdGroupAddressType::DirParty;

    switch(_common.TableId)
    {
        case tableNum(KCS_KBVBuildingProjectTable):
            locKCS_KBVBuildingProjectTable  = _common;
            locKCS_DirProdGroupAddressType  = KCS_DirProdGroupAddressType::KBVBuildingProject;
            break;

        case tableNum(smmBusRelTable):
            locsmmBusRelTable               = _common;
            break;

        case tableNum(CustTable):
            locCustTable                    = _common;
            break;

        case tableNum(DirPartyTable):
            locDirPArtyTable                = _common;
            break;

    }

    ttsbegin;

    mapEnum = _mapProdGroupAddressRanking.getEnumerator();
    while (mapEnum.moveNext())
    {
        productGroupId = mapEnum.currentKey();
        conValues      = mapEnum.currentValue();

        for (cntContainer = 1; cntContainer <= conlen(conValues); cntContainer++)
        {
            [compPartyId, ranking] = conpeek(conValues, cntContainer);
            if (compPartyId == 0)
            {
                continue;
            }
            findRanking = KCS_DirProductGroupAddressRanking::findCommon(productGroupId, _common, ranking, true);

            if (findRanking.RecId)
            {
                if (findRanking.DirPartyId != compPartyId)
                {
                    findRanking.DirPartyId = compPartyId;
                    findRanking.update();
                }
            }
            else
            {
                newRanking.clear();
                newRanking.initValue();
                newRanking.ProductGroupId           = productGroupId;
                newRanking.DirPartyId               = compPartyId;
                newRanking.ProductGrpAddressRanking = ranking;
                newRanking.RefTableId               = _common.TableId;
                newRanking.RefRecId                 = _common.RecId;
                newRanking.KCS_KBVBuildingProjectID = locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
                newRanking.BusRelAccount            = locsmmBusRelTable.BusRelAccount;
                newRanking.CustAccount              = locCustTable.AccountNum;
                newRanking.PartyNumber              = locDirPArtyTable.PartyNumber;
                newRanking.DirProdGroupAddressType  = locKCS_DirProdGroupAddressType;
                newRanking.insert();
            }
        }
    }
    ttscommit;
}

/// <summary>
///    AVA <c>initMapProductGroupAddressRanking</c> method.
/// </summary>
/// <param name="_common">
///    <c>Common</c> as type
/// </param>
/// <returns>
///    <c>Map</c> as return value
/// </returns>
public static Map initMapProductGroupAddressRanking(Common _common)
{
    Map                                 mapProductGrAddrRanking;
    KCS_DirProductGroupAddressRanking   dirProductGroupAddressRanking;
    container                           conAddress;

    Container updateConAddress( DirPartyRecId                   _competitorPartyId,
                                KCS_DirProductGrpAddressRanking _ranking,
                                container                       _conAddress         = connull() )
    {
        container retVal;
        container tmpCon;

        tmpCon = connull();
        tmpCon = conins(tmpCon, conlen(tmpCon) + 1, _competitorPartyId, _ranking);
        retVal = _conAddress;
        if (!confind(_conAddress, tmpCon))
        {
            retVal = conins(_conAddress, conlen(_conAddress) + 1, tmpCon);
        }

        return retVal;
    }

    if (!_common.RecId)
    {
        return null;
    }

    mapProductGrAddrRanking = new Map(Types::String, Types::Container);

    while select dirProductGroupAddressRanking
    order by ProductGroupId, ProductGrpAddressRanking
    where   dirProductGroupAddressRanking.RefTableId    == _common.TableId
        &&  dirProductGroupAddressRanking.RefRecId      == _common.RecId
        &&  dirProductGroupAddressRanking.DirPartyId    != 0
    {

        if (!mapProductGrAddrRanking.exists(dirProductGroupAddressRanking.ProductGroupId))
        {
            mapProductGrAddrRanking.insert(dirProductGroupAddressRanking.ProductGroupId, updateConAddress(  dirProductGroupAddressRanking.DirPartyId, 
                                                                                                            dirProductGroupAddressRanking.ProductGrpAddressRanking));
        }
        else
        {
            conAddress = mapProductGrAddrRanking.lookup(dirProductGroupAddressRanking.ProductGroupId);
            conAddress = updateConAddress(  dirProductGroupAddressRanking.DirPartyId,
                                            dirProductGroupAddressRanking.ProductGrpAddressRanking,
                                            conAddress
                                            );
            mapProductGrAddrRanking.remove( dirProductGroupAddressRanking.ProductGroupId);
            mapProductGrAddrRanking.insert( dirProductGroupAddressRanking.ProductGroupId,
                                            conAddress
                                            );
        }
    }

    return mapProductGrAddrRanking;
}

/// <summary>
///    AVA <c>addMapValueCompPartyId</c> method.
/// </summary>
/// <param name="_conAddress">
///    <c>Container</c> as type
/// </param>
/// <param name="_prodGrpAddrRanking">
///    <c>KCS_DirProductGrpAddressRanking</c> as type
/// </param>
/// <param name="_setCompPartyId">
///    <c>DirPartyRecId</c> as type
/// </param>
/// <returns>
///    <c>Container</c> as return value
/// </returns>
public static container addMapValueCompPartyId( Container                       _conAddress,
                                                KCS_DirProductGrpAddressRanking _prodGrpAddrRanking,
                                                DirPartyRecId                   _setCompPartyId)
{
    container                       retVal;

    int                             cntContainer;
    DirPartyRecId                   competitionPartyId;
    Container                       tmpCon;
    KCS_DirProductGrpAddressRanking prodGrpAddrRanking;
    boolean                         insertValue = false;

    retVal  = _conAddress;

    if (conlen(_conAddress) != 0)
    {
        for (cntContainer = 1; cntContainer <= conlen(_conAddress); cntContainer++)
        {
            [competitionPartyId, prodGrpAddrRanking] = conpeek(_conAddress, cntContainer);
            if (prodGrpAddrRanking == _prodGrpAddrRanking)
            {
                insertValue = true;
                if (_setCompPartyId == 0)
                {
                    retVal = condel(_conAddress, cntContainer, 1);
                    break;
                }
                tmpCon = connull();
                tmpCon = conins(tmpCon, cntContainer, _setCompPartyId, _prodGrpAddrRanking);
                retVal = conpoke(retVal, cntContainer, tmpCon);
                break;
            }
        }
    }

    if (insertValue == false)
    {
        retVal = conins(retVal, conlen(retVal)+1, [_setCompPartyId, _prodGrpAddrRanking]);
    }

    return retVal;
}

/// <summary>
///    AVA <c>findValueCompetionPartyId</c> method.
/// </summary>
/// <param name="_conAddress">
///    <c>Container</c> as type
/// </param>
/// <param name="_prodGrpAddrRanking">
///    <c>KCS_DirProductGrpAddressRanking</c> as type
/// </param>
/// <returns>
///    <c>DirPartyRecId</c> as return value
/// </returns>
public static DirPartyRecId findValueCompetionPartyId(  Container                       _conAddress, 
                                                        KCS_DirProductGrpAddressRanking _prodGrpAddrRanking )
{
    int                             cntContainer;
    DirPartyRecId                   competitionPartyId;
    DirPartyRecId                   tmpCompParty;
    KCS_DirProductGrpAddressRanking prodGrpAddrRanking;

    for (cntContainer = 1; cntContainer <= conlen(_conAddress); cntContainer++)
    {
        [tmpCompParty, prodGrpAddrRanking] = conpeek(_conAddress, cntContainer);
        if (prodGrpAddrRanking == _prodGrpAddrRanking)
        {
            competitionPartyId = tmpCompParty;
        }
    }
    return competitionPartyId;
}

/// <summary>
///    AVA <c>deleteByCustPartyProdGroup</c> method.
/// </summary>
/// <param name="_common">
///    <c>Common</c> as type
/// </param>
/// <param name="_prodGroupId">
///    <c>KCS_DirProductGroupId</c> as type
/// </param>
/// <param name="_ranking">
///    <c>KCS_DirProductGrpAddressRanking</c> as type
/// </param>
public static void deleteByCustPartyProdGroup(  Common                          _common,
                                                KCS_DirProductGroupId           _prodGroupId,
                                                KCS_DirProductGrpAddressRanking _ranking)
{
    KCS_DirProductGroupAddressRanking productGroupAddressRanking;

    ttsbegin;
    delete_from productGroupAddressRanking
    where   productGroupAddressRanking.RefTableId               == _common.TableId
        &&  productGroupAddressRanking.RefRecId                 == _common.RecId
        &&  productGroupAddressRanking.ProductGroupId           == _prodGroupId
        &&  productGroupAddressRanking.ProductGrpAddressRanking == _ranking;

    ttscommit;
}

/// <summary>
///    AVA <c>initValue</c> method.
/// </summary>
public void initValue()
{
    super();

    this.DirProdGroupAddressType = KCS_DirProdGroupAddressType::KBVBuildingProject;
}
